package com.spai.portal.asset.domain;
import java.time.OffsetDateTime;import javax.persistence.*;
@Entity @Table(name="asset_version") public class AssetVersion {@Id private String id;@Column(name="asset_id",nullable=false)private String assetId;@Column(name="version_no",nullable=false)private int versionNo;@Column(name="file_id")private String fileId;@Column(nullable=false)private String status="DRAFT";@Column(name="change_note")private String changeNote;@Column(name="review_note")private String reviewNote;@Column(name="created_by")private String createdBy;@Column(name="created_at",nullable=false)private OffsetDateTime createdAt=OffsetDateTime.now();public String getId(){return id;}public void setId(String id){this.id=id;}public String getAssetId(){return assetId;}public void setAssetId(String assetId){this.assetId=assetId;}public int getVersionNo(){return versionNo;}public void setVersionNo(int versionNo){this.versionNo=versionNo;}public String getFileId(){return fileId;}public void setFileId(String fileId){this.fileId=fileId;}public String getStatus(){return status;}public void setStatus(String status){this.status=status;}public String getChangeNote(){return changeNote;}public void setChangeNote(String changeNote){this.changeNote=changeNote;}public String getReviewNote(){return reviewNote;}public void setReviewNote(String reviewNote){this.reviewNote=reviewNote;}public String getCreatedBy(){return createdBy;}public void setCreatedBy(String createdBy){this.createdBy=createdBy;}public OffsetDateTime getCreatedAt(){return createdAt;}public void setCreatedAt(OffsetDateTime createdAt){this.createdAt=createdAt;}}
